import sys

s = sys.stdin.read().split()[0]
INF = float('inf')
# dp[p] = minimum operations so far with p = parity of the number of flips applied to the current position
dp = [0, INF]
for c in s:
    nd = [INF, INF]
    for p in (0, 1):
        if dp[p] == INF:
            continue
        for flip in (0, 1):
            q = p ^ flip
            if int(c) ^ q == 1:
                nd[q] = min(nd[q], dp[p] + flip)
    dp = nd
print(min(dp))

